						key: cell.key,
						'data-cabinet-node': '1',
						'data-cabinet-family': cell.familyColor,
						// 分层后每层 ≤3 卡：basis=(可用宽-2列距)/3——460/600 右栏分别
					// 约 141/184px；360px 右栏收缩到 ~104px 仍保 3 个一行（用户硬
